import{_ as e,o as r,c as i,a2 as t}from"./chunks/framework.BME6yAZ4.js";const _=JSON.parse('{"title":"半小时课程","description":"用一个真实办公任务，了解智能体原理，学会交流与验收，并把做对的流程保存为技能。","frontmatter":{"title":"半小时课程","description":"用一个真实办公任务，了解智能体原理，学会交流与验收，并把做对的流程保存为技能。"},"headers":[],"relativePath":"30min/index.md","filePath":"30min/index.md","lastUpdated":1786896277000}'),l={name:"30min/index.md"};function n(o,a,s,d,c,h){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="半小时-·-用好办公智能体" tabindex="-1">半小时 · 用好办公智能体 <a class="header-anchor" href="#半小时-·-用好办公智能体" aria-label="Permalink to &quot;半小时 · 用好办公智能体&quot;">​</a></h1><p>这半小时只练一件真实的事：<strong>把今天的工作讨论会变成明天能执行的工作安排。让智能体读取会议纪要、工作群消息和团队日历，生成任务与日程草稿；你确认关键内容后，再由它调用工具完成创建和通知。</strong></p><p>你不需要会编程，也不需要背术语。沿着下面三件事走一遍，就能从“让 AI 回答问题”走到“和办公智能体配合完成工作”。</p><h2 id="_01-了解背后基本原理" tabindex="-1">01 了解背后基本原理 <a class="header-anchor" href="#_01-了解背后基本原理" aria-label="Permalink to &quot;01 了解背后基本原理&quot;">​</a></h2><ul><li><a href="/ai-general-course/30min/era">模型、工具和智能体分别做什么</a> — 看懂回答问题、调用工具和完成真实任务的区别</li></ul><h2 id="_02-学会和智能体交流" tabindex="-1">02 学会和智能体交流 <a class="header-anchor" href="#_02-学会和智能体交流" aria-label="Permalink to &quot;02 学会和智能体交流&quot;">​</a></h2><ul><li><a href="/ai-general-course/30min/context">提供高质量的上下文</a> — 选择真实、相关、最新且足够完整的任务资料</li><li><a href="/ai-general-course/30min/workflow">把任务交代清楚</a> — 说清目标、资料范围、工作步骤、产出和质量标准</li><li><a href="/ai-general-course/30min/output">明确产出物质量怎么评估</a> — 检查内容是否真实、完整、可执行，工具动作是否真正落地</li></ul><h2 id="_03-固定技能重复使用" tabindex="-1">03 固定技能重复使用 <a class="header-anchor" href="#_03-固定技能重复使用" aria-label="Permalink to &quot;03 固定技能重复使用&quot;">​</a></h2><ul><li><a href="/ai-general-course/30min/automate">把验证过的流程保存为技能</a> — 保存材料、工具步骤、确认点和检查清单，下次直接复用</li></ul><p>学完后的最低成果不是“听懂了”，而是能把一项真实办公任务交给智能体，能验收它的产出，并知道什么时候让它继续、什么时候由你判断和确认。</p>',10)])])}const m=e(l,[["render",n]]);export{_ as __pageData,m as default};
